import json, numpy as np
def transform(grid):
    g=np.array(grid); h,w=g.shape; a,b=h//3,w//3
    out=np.zeros((a,b),int)
    for i in range(a):
        for j in range(b):
            c=set(g[3*i:3*i+3,3*j:3*j+3].flatten())-{0,5}
            if len(c)==1: out[i,j]=list(c)[0]
    return out.tolist()
